import re
G={"core":[],"worlds":["core"],"baselines":["core","worlds"],"store":["core"],"evaluate":["core","store","baselines"],
"learners":["core","evaluate","store","worlds","signoff"],"coevo":["core","learners","evaluate","store","worlds","signoff"],
"reference":["core","evaluate","store","worlds"],"replay":["core","store","worlds","baselines"],"signoff":["store"]}
def cl(n,s=None):
    s=set() if s is None else s
    for d in G[n]:
        if d not in s: s.add(d); cl(d,s)
    return s
t=open('docs/packages/rllab/contract.md').read()
cur=None
for line in t.splitlines():
    m=re.match(r'^#+ .*?`?(\w+)\.(\w+)',line)
    if m and m.group(1) in G: cur=m.group(1),m.group(2)
    m=re.match(r'- \*\*Used by:\*\* (.*)',line)
    if m and cur:
        users=[u.strip() for u in m.group(1).split(';')[0].split(',')]
        for u in users:
            if u in G and u!=cur[0] and cur[0] not in cl(u):
                print(f"{u} -> {cur[0]} ({cur[0]}.{cur[1]}) not allowed")
